<script setup lang="ts">import{ref,onMounted,computed,watch}from 'vue';import{useRoute}from 'vue-router';import{lab,load}from '../stores/research';import{canEdit,isAdmin}from '../stores/auth';import*as notes from '../api/notes';import{download}from '../api/client';import{useTask}from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import RevisionBadge from '../components/RevisionBadge.vue';const route=useRoute(),run=ref(Number(route.query.run)||0),title=ref('预设湿度层独立复验说明'),interpretation=ref('核对总体与分层成功率方向，以及固定边际条件双侧证据，不将共同OR或p值解释为封装因果效果。'),action=ref('保持预设湿度层，补充独立试片并记录封装批次、浸湿条件和原始四格。'),comment=ref('层边际和精确双侧定义已核对，按预设方案开展独立复验。'),notice=ref(''),{error,execute}=useTask();const eligible=computed(()=>lab.runs.filter(r=>r.status==='completed'&&!r.stale));const selectedRun=computed(()=>lab.runs.find(r=>r.id===run.value));const canCreate=computed(()=>eligible.value.some(r=>r.id===run.value));onMounted(()=>execute(async()=>{await load();run.value=run.value||eligible.value[0]?.id||0}));watch(run,()=>{const r=lab.runs.find(x=>x.id===run.value);if(r?.stale)notice.value=''})
function create(){execute(async()=>{await notes.create({title:title.value,run_id:run.value,interpretation:interpretation.value,action:action.value});notice.value='复验说明已建立，等待负责人审阅';await load()})}function review(id:number,decision:string){execute(async()=>{await notes.review(id,decision,comment.value);await load();notice.value='审阅状态已保存'})}function exportNote(id:number){execute(()=>download('/notes/'+id+'/export','cenan-observation-'+id+'.csv'))}function rev(x:number|null){return x===null?'未记录旧版':String(x)}</script><template><PageHeading index="05" title="让分层证据，落到独立复验。" text="研究员起草，负责人审阅，阅读者只下载已批准说明。每份说明标明所属底稿版本；过期研究不能新建或批准说明，已批准说明仍按原快照导出。"/><ErrorNotice :message="error" @retry="execute(load)"/><p v-if="notice" class="success" role="status">{{notice}}</p><div class="notes-layout"><form v-if="canEdit" @submit.prevent="create"><p class="eyebrow">NEW VERIFICATION NOTE</p><label>关联研究<select v-model="run" aria-label="关联研究"><option v-for="r in eligible" :value="r.id">#{{r.id}} {{r.name}}（底稿 v{{r.worksheet_revision??'旧版'}}）</option></select><small v-if="!eligible.length" class="stale-note">没有与当前底稿版本一致的已完成研究；请先按当前底稿重新冻结计算。</small></label><p v-if="selectedRun?.stale" class="stale-banner"><b>所选研究已过期。</b>冻结底稿 v{{rev(selectedRun.worksheet_revision)}}，当前 v{{selectedRun.current_revision}}。不能基于过期研究新建说明。</p><label>说明名称<input v-model="title" required minlength="3"></label><label>复验解释<textarea v-model="interpretation" rows="5" required minlength="8"/></label><label>复验动作<textarea v-model="action" rows="4" required minlength="5"/></label><button class="primary" :disabled="!canCreate">保存复验说明 →</button></form><section><div class="section-title"><h2>复验档案</h2><span>{{lab.notes.length}}份</span></div><label v-if="isAdmin">审阅意见<textarea v-model="comment" rows="2"/></label><article v-for="n in lab.notes" class="observation-note"><div><p class="eyebrow">NOTE {{n.id}} / RUN {{n.run_id}}</p><StatusBadge :status="n.status"/></div><h2>{{n.title}}</h2><p class="revision-line"><RevisionBadge :frozen="n.worksheet_revision" :current="n.current_revision" :stale="n.stale"/></p><p>{{n.interpretation}}</p><p class="action-note">{{n.action}}</p><p v-if="n.review_comment" class="review-comment">{{n.approved_by}} · {{n.review_comment}}</p><p v-if="n.stale&&n.status==='approved'" class="stale-note">关联底稿已修订；本说明仍按冻结快照 v{{rev(n.worksheet_revision)}} 导出，导出CSV同时标注当前版本。</p><p v-else-if="n.stale&&n.status==='draft'" class="stale-note">关联研究已过期，不能批准；请基于当前底稿重新冻结并重建说明。</p><div class="actions"><button v-if="isAdmin&&n.status==='draft'&&!n.stale" class="primary" @click="review(n.id,'approved')">批准说明</button><button v-if="isAdmin&&n.status==='draft'" class="outline" @click="review(n.id,'rejected')">退回</button><button v-if="n.status==='approved'" class="outline" @click="exportNote(n.id)">下载获批CSV ↗</button></div></article></section></div></template>
